custom_css:
@import url('https://fonts.googleapis.com/css2?family=Mona+Sans:wdth,wght@75..125,200..900&family=Chivo+Mono:wght@300;400;500;600&display=swap');

:root{--vb-mono:'Chivo Mono',ui-monospace,Menlo,monospace;--scrollbar-thumb:#B7BFC6}
::selection{background:#005098;color:#fff}
:focus-visible{outline:2px solid #005098;outline-offset:2px}

/* ============ MISE AU POINT : l'entrée des pages (flou -> netteté) ============ */
@keyframes vb-mise-au-point{
  0%{opacity:0;filter:blur(7px);transform:scale(1.008)}
  55%{opacity:1}
  100%{opacity:1;filter:blur(0);transform:none}
}
/* Verrouillage : les équerres arrivent larges et se posent */
@keyframes vb-verrou{
  0%{opacity:0;transform:scale(2.4)}
  38%{opacity:1}
  72%{transform:scale(.94)}
  100%{opacity:1;transform:none}
}

/* ============ COQUE (jamais dans les pages : une page peut avoir sa propre .sidebar) ============ */
body:has(#nav-section) .sidebar{
  background:#112E43;color:#EDF2F7;
  --text-primary:#EDF2F7;--text-secondary:#B4BFCA;--text-muted:#A3B0BD;
  --accent:#80C7F8;--accent-hover:#fff;--bg-card:#1E3E55;--bg-card-hover:#1E3E55;
}
body:has(#nav-section) .sidebar .brand{padding-top:20px;padding-bottom:14px}
body:has(#nav-section) .brand-name{
  position:relative;display:inline-block;color:#fff;margin-left:16px;
  font-family:'Mona Sans','Helvetica Neue',Arial,sans-serif!important;
  font-weight:230;font-size:34px;line-height:1;letter-spacing:-.015em;
  font-variation-settings:'wdth' 116;
}
body:has(#nav-section) .brand-name .g-letter{-webkit-text-fill-color:#fff!important;text-shadow:none!important}
body:has(#nav-section) .brand .brand-version{font-family:var(--vb-mono);font-size:10px;letter-spacing:.1em;color:#BCC7D1;margin-right:16px}

body:has(#nav-section) #nav-section a.nav-item,body:has(#nav-section) #nav-section .nav-group-toggle{color:#B4BFCA;border-radius:2px;font-weight:500;letter-spacing:.005em}
body:has(#nav-section) #nav-section a.nav-item:hover,body:has(#nav-section) #nav-section .nav-group-toggle:hover{background:rgba(255,255,255,.07);color:#fff}
body:has(#nav-section) #nav-section a.nav-item.active{color:#fff;background-color:#1E3E55;background-image:linear-gradient(#80C7F8,#80C7F8), linear-gradient(#80C7F8,#80C7F8), linear-gradient(#80C7F8,#80C7F8), linear-gradient(#80C7F8,#80C7F8), linear-gradient(#80C7F8,#80C7F8), linear-gradient(#80C7F8,#80C7F8), linear-gradient(#80C7F8,#80C7F8), linear-gradient(#80C7F8,#80C7F8);background-repeat:no-repeat;background-position:left 4px top 4px, left 4px top 4px, right 4px top 4px, right 4px top 4px, left 4px bottom 4px, left 4px bottom 4px, right 4px bottom 4px, right 4px bottom 4px;background-size:7px 1.5px, 1.5px 7px, 7px 1.5px, 1.5px 7px, 7px 1.5px, 1.5px 7px, 7px 1.5px, 1.5px 7px}
body:has(#nav-section) #nav-section a.nav-item.active::before{display:none!important}
body:has(#nav-section) #nav-section .nav-group-toggle{font-size:11px;font-weight:600;letter-spacing:.14em;text-transform:uppercase}
body:has(#nav-section) #nav-section .nav-item-text{display:flex;align-items:center;gap:8px;flex-wrap:nowrap}
body:has(#nav-section) #nav-section .nav-badge{margin-left:auto;color:#082032!important}
body:has(#nav-section) #nav-section .nav-icon-ms{color:inherit;opacity:1}
body:has(#nav-section) #nav-section a.nav-item.active .nav-icon-ms{color:#80C7F8}
body:has(#nav-section) #nav-section .nav-chevron{opacity:.85}

/* Fenêtre de brume sous la marque : un poteau tient l'horizon, l'équerre est posée dessus */
body:has(#nav-section) [data-slot="nav-head"]{
  display:block;position:relative;height:92px;margin:2px 16px 12px;overflow:hidden;
  border-radius:2px;background:#082032 url(/api/themes/studio/assets/at-f39a8ff04e/virage-bande.webp?v=3) 50% 50%/cover no-repeat;
}
body:has(#nav-section) [data-slot="nav-head"]::after{
  content:"";position:absolute;left:50%;top:46%;width:22px;height:42px;margin:-21px 0 0 -11px;
  pointer-events:none;background-image:linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098);background-repeat:no-repeat;background-position:left 0px top 0px, left 0px top 0px, right 0px top 0px, right 0px top 0px, left 0px bottom 0px, left 0px bottom 0px, right 0px bottom 0px, right 0px bottom 0px;background-size:8px 1.5px, 1.5px 8px, 8px 1.5px, 1.5px 8px, 8px 1.5px, 1.5px 8px, 8px 1.5px, 1.5px 8px;
}
/* Gamme de gris virée au bleu, onze plages, au-dessus du widget système */
body:has(#nav-section) [data-slot="nav-foot"]{display:block;height:5px;margin:10px 16px 6px;background:linear-gradient(90deg,#060A10 0.0000% 9.0909%,#0C1825 9.0909% 18.1818%,#12263B 18.1818% 27.2727%,#183450 27.2727% 36.3636%,#375069 36.3636% 45.4545%,#566D83 45.4545% 54.5455%,#75899C 54.5455% 63.6364%,#94A5B4 63.6364% 72.7273%,#B2BFCA 72.7273% 81.8182%,#D0D8DF 81.8182% 90.9091%,#EEF2F5 90.9091% 100.0000%)}
body:has(#nav-section) .sidebar.collapsed [data-slot="nav-head"],body:has(#nav-section) .sidebar.collapsed [data-slot="nav-foot"]{display:none}

/* Widget système : jauges en plages */
body:has(#nav-section) .sidebar-footer{background:#082032}
body:has(#nav-section) .sidebar-footer .status-label{font-family:var(--vb-mono);font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:#B4BFCA}
body:has(#nav-section) .sys-monitor .smon-label{font-family:var(--vb-mono);font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:#B4BFCA}
body:has(#nav-section) .sys-monitor .smon-val{font-family:var(--vb-mono);font-size:11px;font-variant-numeric:tabular-nums;color:#EDF2F7}
body:has(#nav-section) .sys-monitor .smon-bar{
  height:6px;border-radius:0;background:rgba(255,255,255,.16);overflow:hidden;
  -webkit-mask-image:repeating-linear-gradient(90deg,#000 0 4px,transparent 4px 6px);
  mask-image:repeating-linear-gradient(90deg,#000 0 4px,transparent 4px 6px);
}
body:has(#nav-section) .sys-monitor .smon-fill{border-radius:0}
body:has(#nav-section) .sys-monitor .smon-section-label{font-family:var(--vb-mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:#B4BFCA}

/* ============ BARRE DU HAUT ============ */
body:has(#nav-section) .topbar{background:transparent;color:#081019}
body:has(#nav-section) .breadcrumb,body:has(#nav-section) .breadcrumb-current{font-family:var(--vb-mono);font-size:12px;letter-spacing:.08em;text-transform:uppercase}
body:has(#nav-section) .breadcrumb-sep{color:#242F3B;opacity:1}
body:has(#nav-section) .breadcrumb-current{color:#081019;font-weight:600}
body:has(#nav-section) .search-trigger{background:#D1D7DC;color:#242F3B;border-radius:2px}
body:has(#nav-section) .btn-new-task{background:#081019!important;color:#fff!important;border:0!important;border-radius:2px;font-weight:600}
body:has(#nav-section) .topbar-btn{color:#081019;border-radius:2px}
.cmd-overlay{background:rgba(9,33,52,.46)!important;backdrop-filter:blur(7px)!important}

/* ============ PAGES : la même langue partout ============ */
[data-part="page-head"] h1,[data-part="page-head"] [data-part="title"]{
  font-weight:200;font-size:clamp(38px,4.1vw,60px);line-height:.98;letter-spacing:-.034em;
  font-variation-settings:'wdth' 122;
}
:root body{font-family:'Mona Sans','Helvetica Neue',Arial,sans-serif}
:root body :where(button,input,select,textarea){font-family:inherit}
html[data-page="chat"][data-page-head] body .session-title-bar.session-title-bar{
  font-weight:200!important;font-size:clamp(24px,2.3vw,32px)!important;line-height:1.1!important;
  letter-spacing:-.026em!important;font-variation-settings:'wdth' 122;
}
.kpi-card::before{height:0!important}
.btn kbd,[data-part="btn"] kbd{background:rgba(8,16,25,.3)!important;color:#fff!important}
span.n,.cat-count{color:#081019}
.zone-title{font-size:11px;font-weight:600;letter-spacing:.15em;text-transform:uppercase;color:#242F3B}
.stat-num,[data-part="stat"] .num{font-family:var(--vb-mono);font-weight:300;letter-spacing:-.04em;font-variant-numeric:tabular-nums}
[data-part="chip"],.badge{font-size:10.5px}
td,th,[data-part="stat"]{font-variant-numeric:tabular-nums}
.fbtn:not(.active):not(.on){color:#081019!important}
.badge-imported{color:#4B2380!important}
.j-agent-badge.j-agent-codex{color:#1D6B2B!important}
.agent-pref-item:first-child :is(.agent-pref-rank,.agent-pref-badge){color:#fff}

/* Les barres d'état à gauche des lignes deviennent un voile de teinte */
[data-part="row"].active-task-item,[data-part="row"].ac-item{border-left-width:0!important}
.active-task-item,.ac-item.ac-running{background-image:linear-gradient(90deg,rgba(0,80,147,.14),transparent 48%)}
.ac-item.ac-success{background-image:linear-gradient(90deg,rgba(0,105,74,.12),transparent 48%)}
.ac-item[class*="ac-err"],.ac-item[class*="ac-fail"]{background-image:linear-gradient(90deg,rgba(162,25,33,.12),transparent 48%)}
.ac-block-tag{border-width:0!important;background-color:color-mix(in srgb,currentColor 10%,transparent)}

/* L'élément sélectionné est verrouillé par l'équerre (pseudo-élément : le fond de la carte, sa barre de progression, restent intacts) */
@keyframes vb-verrou-pse{
  0%{opacity:0;transform:scale(1.04,1.32)}
  60%{opacity:1}
  100%{opacity:1;transform:none}
}
:is([data-part="row"],[data-part="surface"]):is(.sel,.selected,.is-selected,[aria-selected="true"],[data-selected="true"]){position:relative}
:is([data-part="row"],[data-part="surface"]):is(.sel,.selected,.is-selected,[aria-selected="true"],[data-selected="true"])::after{
  content:"";position:absolute;inset:3px;pointer-events:none;background-image:linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098);background-repeat:no-repeat;background-position:left 0px top 0px, left 0px top 0px, right 0px top 0px, right 0px top 0px, left 0px bottom 0px, left 0px bottom 0px, right 0px bottom 0px, right 0px bottom 0px;background-size:8px 1.5px, 1.5px 8px, 8px 1.5px, 1.5px 8px, 8px 1.5px, 1.5px 8px, 8px 1.5px, 1.5px 8px;
  animation:vb-verrou-pse .34s cubic-bezier(.2,.8,.2,1) both;
}

/* Vignettes : virées au bleu au repos, en couleur sous le doigt */
[data-part="media"]:hover{filter:none!important}

/* Écran vide du Chat : le même poteau, la même équerre */
[data-slot="chat-empty"]{
  display:block;position:relative;width:min(100%,560px);aspect-ratio:2.4/1;margin:0 auto 22px;
  border-radius:3px;background:url(/api/themes/studio/assets/at-f39a8ff04e/virage-large.webp?v=3) 50% 50%/cover no-repeat;
}
[data-slot="chat-empty"]::after{
  content:"";position:absolute;left:50%;top:50%;width:26px;height:50px;margin:-25px 0 0 -13px;
  pointer-events:none;background-image:linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098), linear-gradient(#005098,#005098);background-repeat:no-repeat;background-position:left 0px top 0px, left 0px top 0px, right 0px top 0px, right 0px top 0px, left 0px bottom 0px, left 0px bottom 0px, right 0px bottom 0px, right 0px bottom 0px;background-size:8px 1.5px, 1.5px 8px, 8px 1.5px, 1.5px 8px, 8px 1.5px, 1.5px 8px, 8px 1.5px, 1.5px 8px;
}

@media (max-width:860px){
  a.nav-item,.nav-group-toggle,.btn,[data-part="btn"],[data-part="iconbtn"],[data-part="tab"]{min-height:44px}
  body:has(#nav-section) .search-trigger kbd{display:none}
}

/* ============ APP ANDROID : le bouton de menu devient le rail ============ */
html body.companion-app .menu-toggle{
  background:#112E43!important;color:#EDF2F7!important;margin:0!important;width:44px!important;
  flex:0 0 44px!important;border-radius:0!important;
}
body.companion-app .bottom-tabs{background:#112E43}
body.companion-app .btab{color:#B4BFCA;opacity:1}
body.companion-app .btab.active{color:#fff;background-color:#1E3E55;background-image:linear-gradient(#80C7F8,#80C7F8), linear-gradient(#80C7F8,#80C7F8), linear-gradient(#80C7F8,#80C7F8), linear-gradient(#80C7F8,#80C7F8), linear-gradient(#80C7F8,#80C7F8), linear-gradient(#80C7F8,#80C7F8), linear-gradient(#80C7F8,#80C7F8), linear-gradient(#80C7F8,#80C7F8);background-repeat:no-repeat;background-position:left 4px top 4px, left 4px top 4px, right 4px top 4px, right 4px top 4px, left 4px bottom 4px, left 4px bottom 4px, right 4px bottom 4px, right 4px bottom 4px;background-size:7px 1.5px, 1.5px 7px, 7px 1.5px, 1.5px 7px, 7px 1.5px, 1.5px 7px, 7px 1.5px, 1.5px 7px}

/* ============ AMBIANCE : seulement si le mouvement est permis ============ */
@media (prefers-reduced-motion:no-preference){
  body:has(#nav-section) [data-slot="nav-head"]::after{animation:vb-verrou 1300ms cubic-bezier(.2,.8,.2,1) 520ms both}
  [data-slot="chat-empty"]::after{animation:vb-verrou 1300ms cubic-bezier(.2,.8,.2,1) 300ms both}
}
@media (prefers-reduced-motion:reduce){
  :root{--enter-animation:none}
}
